    it('renders the hostile golden without live MDX', async () => {
      const reference = await convertGo(golden('hostile'));
      const processor = unified().use(remarkParse).use(remarkMdx);
      const live = (mdx: string) => {
        const tree = processor.parse(preprocessCustomHeadingIds(mdx));
        const types: string[] = [];
        visit(tree, (node) => {
          if (/^mdx(?:jsEsm|FlowExpression|TextExpression)$/.test(node.type)) types.push(node.type);
          const url = (node as { url?: string }).url;
          if (url !== undefined && /^\s*(?:javascript|data|vbscript):/i.test(url)) {
            types.push(`${node.type}:${url}`);
          }
          if (node.type === 'mdxJsxFlowElement' || node.type === 'mdxJsxTextElement') {
            const name = (node as { name?: string | null }).name ?? '';
            if (!['ResponseField', 'Warning', 'code', 'Steps', 'Step'].includes(name))
              types.push(`jsx:${name}`);
          }
        });
        return types;
      };
      for (const entry of reference.pages) {
        expect(live(entry.content), entry.slug).toEqual([]);
        if (entry.intro) expect(live(entry.intro), `${entry.slug} intro`).toEqual([]);
      }
      const overview = page(reference, 'package-overview');
      expect(overview.content).toContain('&#105;mport x from "y"');
      expect(overview.content).toContain('&#101;xport GOPRIVATE=example.com/\\*');
      const record = page(reference, 'Record');
      expect(record.content).toContain('**Tag:** `json:"raw" extra:"{alert(1)}"`');
      expect(record.content).not.toMatch(/\n\n\{alert/);
      const intro = overview.intro ?? '';
      expect(intro).toContain('&#105;mport fs from "node:fs"');
      expect(intro).toContain('&#101;xport default function X()\\{}');
      expect(intro).toContain('Env\n\n&#101;xport FOO=bar');
      expect(intro).toContain('first\n\n&#105;mport os from "node:os"');
      expect(intro).toContain('&#105;mport starts this paragraph after an inline tag.');
      expect(page(reference, 'Do').content).toContain('&#101;xport is the first word after a tag.');
      expect(intro).toContain('&#105;mport x from "y"');
      expect(intro).toContain('&#101;xport const a = 1');
      expect(intro).toContain('See one, two, three, and four.');
      expect(page(reference, 'Do').content).toContain('&#105;mport x from "y"');
    });

