    it('widens code fences past any backtick run in tags, types, and code', async () => {
      const fenced = 'x\n```\n{alert(1)}\nimport x from "y"\n````\n{alert(2)}';
      const reference = await convertGo(
        await artifact('fences', [
          {
            importPath: 'example.com/acme',
            name: 'acme',
            dir: '.',
            doc: 'Package acme is the client.',
            examples: [{ code: fenced, output: fenced }],
            types: [
              {
                name: 'Record',
                kind: 'struct',
                decl: [{ t: `type Record struct{} // ${fenced}` }],
                fields: [
                  { name: 'A', type: [{ t: 'string' }], tag: 'a`{alert(1)}`b' },
                  { name: 'B', type: [{ t: 'string' }], tag: '`lead' },
                  { name: 'C', type: [{ t: 'string' }], tag: 'trail`' },
                ],
                methods: [
                  {
                    name: 'Do',
                    decl: [{ t: 'func (r Record) Do() string' }],
                    results: [{ type: [{ t: 'a``{alert(3)}``b' }] }],
                  },
                ],
              },
            ],
          },
        ])
      );
      expectNoLiveMdx(reference);
      const record = page(reference, 'Record').content;
      expect(record).toContain('**Tag:** ``a`{alert(1)}`b``');
      expect(record).toContain('**Tag:** `` `lead ``');
      expect(record).toContain('**Tag:** `` trail` ``');
      expect(record).toContain('```a``{alert(3)}``b```');
      expect(record).toContain('`````go\ntype Record struct{}');
      expect(page(reference, 'package-overview').content).toContain('`````go\nx\n```');
    });

