  describe('artifact validation', () => {
    let dir: string;

    beforeAll(async () => {
      dir = await mkdtemp(path.join(os.tmpdir(), 'go-artifact-'));
    });

    afterAll(async () => {
      await rm(dir, { recursive: true, force: true });
    });

    it('rejects unsupported schema versions', async () => {
      const file = path.join(dir, 'future.json');
      await writeFile(file, JSON.stringify({ schemaVersion: 2, packages: [] }));
      await expect(convertGo(file)).rejects.toThrow(
        'uses schema version 2, but Mintlify reads schema version 1'
      );
    });

    it('rejects malformed artifacts', async () => {
      const file = path.join(dir, 'invalid.json');
      await writeFile(
        file,
        JSON.stringify({
          schemaVersion: 1,
          generator: { name: 'mintlify-go-extractor', version: 'test', go: 'go1.22' },
          module: 'example.com/acme',
          goos: 'linux',
          goarch: 'amd64',
          commentSyntax: 'markdown',
          packages: [{ importPath: 'example.com/acme', name: 'acme' }],
        })
      );
      await expect(convertGo(file)).rejects.toThrow(
        'Invalid Go SDK artifact ' + file + ': packages.0.dir'
      );
    });
  });
